#nullable enable
using FluentValidation;

namespace HourBooking.Slices.Booking;

/// <summary>
/// The same two periphery rules as book-hours, and deliberately not shared with it. They are the same
/// CONSTRAINT on hours but two separate business rules in the model, each with its own GWT and its own
/// wording from the domain expert — "employees may never book 0 hours" versus "a correction cannot
/// take the hours to zero". Merging them would make one rule's change silently alter the other's.
/// </summary>
public sealed class CorrectHoursValidator : AbstractValidator<CorrectHours>
{
    public CorrectHoursValidator()
    {
        // HoursMustBeNonZero — a correction cannot take the hours to zero. Removal is the only way to
        // take a line back, which is why BookingRemoved is a distinct event rather than a 0-hour
        // correction.
        RuleFor(x => x.Hours)
            .GreaterThan(0m)
            .WithMessage("HoursMustBeNonZero");

        // HoursMustBeWholeOrHalf — "Full hours or 0,5 hours."
        RuleFor(x => x.Hours)
            .Must(h => h % 0.5m == 0m)
            .WithMessage("HoursMustBeWholeOrHalf");
    }
}

/// <summary>
/// The command as the model declares it. bookingId identifies the booking being corrected — the row
/// the screen was looking at, which is the OTHER meaning of bookingId that book-hours had to treat as
/// terminal="generated". Same name, opposite direction, and here it really is the row.
/// </summary>
public sealed record CorrectHours(Guid BookingId, Guid EmployeeId, string Month, decimal Hours, string? Note);
